'use strict';class ProgressSystem{constructor(){this.pages=[ 'welcome','bio','writing','quotes','questions','investments' ];this.currentPersona=Storage.getPersona();this.progress=this.loadProgress()|| this.initializeProgress();this.currentPage=this.getCurrentPage();this.counterTimer=null;this.observer=null;if(!this.progress.pagesVisited){this.progress.pagesVisited=[];}if(!this.progress.initialized){if(!this.progress.pagesVisited.includes(this.currentPage)){this.progress.pagesVisited.push(this.currentPage);}this.progress.initialized=true;this.saveProgress();}this.startTracking();this.updateUI();this.listenForPersonaChanges();}initializeProgress(){return{initialized: false,pagesVisited: [],totalProgress: 0,expireDate: Storage.getExpirationDate()};}loadProgress(){const key=AppConstants.STORAGE_KEYS.READING_PROGRESS(this.currentPersona);const saved=localStorage.getItem(key);if(!saved){return null;}try{const data=JSON.parse(saved);if(data.timestamp && data.progress){return data.progress;}if(data.expireDate && Date.now()> data.expireDate){localStorage.removeItem(key);return null;}if(!data.expireDate){data.expireDate=Storage.getExpirationDate();this.saveProgress();}return data;}catch(error){console.error('Progress System: Error parsing saved progress',error);return null;}}saveProgress(persona=null){const targetPersona=persona || this.currentPersona;const actualPersona=Storage.getPersona();if(targetPersona !==actualPersona){return;}const key=AppConstants.STORAGE_KEYS.READING_PROGRESS(targetPersona);try{localStorage.setItem(key,JSON.stringify(this.progress));}catch(error){console.error('Progress System: Error saving progress',error);}}getCurrentPage(){const path=window.location.pathname;if(path==='/' || path==='/index.html' || path==='/#welcome'){return 'welcome';}const hash=window.location.hash.replace('#','');if(hash && this.pages.includes(hash)){return hash;}const pageName=path.replace('/','').replace('.html','');return this.pages.includes(pageName)? pageName : 'welcome';}startTracking(){const checkPageChange=()=>{const activeLink=document.querySelector('.nav-link.active');if(activeLink){const newPage=activeLink.dataset.page || 'welcome';if(newPage !==this.currentPage){this.currentPage=newPage;this.onPageChange();}}};this.observer=new MutationObserver(()=>{checkPageChange();});const navElement=document.querySelector('.nav-list');if(navElement){this.observer.observe(navElement,{attributes: true,attributeFilter: ['class'],subtree: true});}document.addEventListener('click',(e)=>{if(e.target.closest('.nav-link')){setTimeout(()=>{checkPageChange();},AppConstants.ANIMATION.FAST);}});window.addEventListener('hashchange',()=>{checkPageChange();});window.addEventListener('popstate',()=>{checkPageChange();});}onPageChange(){if(!this.progress.pagesVisited){this.progress.pagesVisited=[];}if(!this.progress.pagesVisited.includes(this.currentPage)){this.progress.pagesVisited.push(this.currentPage);this.showXPGain();}this.calculateTotalProgress();this.saveProgress();this.updateUI();}calculateTotalProgress(){if(!this.progress.pagesVisited){this.progress.pagesVisited=[];}const visitedCount=Math.min(this.progress.pagesVisited.length,this.pages.length);this.progress.totalProgress=Math.min(100,Math.floor((visitedCount/this.pages.length)*100));}showXPGain(){const xpText=document.getElementById('progressPercentage');if(xpText){xpText.style.transform='scale(1.3)';xpText.style.transition='transform 0.3s ease';setTimeout(()=>{xpText.style.transform='scale(1)';},AppConstants.ANIMATION.NORMAL);}}updateUI(){this.calculateTotalProgress();const targetPercentage=Math.max(0,Math.min(100,this.progress.totalProgress || 0));const progressBarFill=document.getElementById('progressBarFill');if(progressBarFill){progressBarFill.style.width=`${targetPercentage}%`;}const progressPercentage=document.getElementById('progressPercentage');if(progressPercentage){const currentText=progressPercentage.textContent.replace('%','').trim();let currentValue=parseInt(currentText)|| 0;if(isNaN(currentValue)|| currentValue < 0 || currentValue > 100){currentValue=0;}this.animateCounter(progressPercentage,currentValue,targetPercentage);}}animateCounter(element,start,end){if(this.counterTimer){clearInterval(this.counterTimer);this.counterTimer=null;}start=parseInt(start)|| 0;end=parseInt(end)|| 0;start=Math.max(0,Math.min(100,start));end=Math.max(0,Math.min(100,end));if(start===end){element.textContent=`${end}%`;return;}const duration=AppConstants.ANIMATION.NORMAL;const range=Math.abs(end-start);const increment=end > start ? 1 :-1;const stepTime=Math.max(10,Math.floor(duration/range));let current=start;this.counterTimer=setInterval(()=>{current+=increment;current=Math.max(0,Math.min(100,current));if((increment > 0 && current >=end)||(increment < 0 && current <=end)){current=Math.max(0,Math.min(100,end));element.textContent=`${current}%`;clearInterval(this.counterTimer);this.counterTimer=null;}else{element.textContent=`${current}%`;}},stepTime);}listenForPersonaChanges(){window.addEventListener('storage',(e)=>{if(e.key===AppConstants.STORAGE_KEYS.PERSONA && e.newValue !==this.currentPersona){this.handlePersonaChange(e.newValue);}});window.addEventListener('personaChanged',(e)=>{if(e.detail && e.detail.persona !==this.currentPersona){this.handlePersonaChange(e.detail.persona);}});}handlePersonaChange(newPersona){const oldPersona=this.currentPersona;this.saveProgress(oldPersona);this.currentPersona=newPersona;const savedProgress=this.loadProgress();if(savedProgress){this.progress=savedProgress;}else{this.progress=this.initializeProgress();const currentPage=this.getCurrentPage();if(!this.progress.pagesVisited.includes(currentPage)){this.progress.pagesVisited.push(currentPage);}this.progress.initialized=true;this.saveProgress(newPersona);}this.currentPage=this.getCurrentPage();this.calculateTotalProgress();this.updateUI();}destroy(){if(this.observer){this.observer.disconnect();this.observer=null;}if(this.counterTimer){clearInterval(this.counterTimer);this.counterTimer=null;}}}(function(){function init(){if(window.progressSystem){if(window.progressSystem.destroy){window.progressSystem.destroy();}}window.progressSystem=new ProgressSystem();}if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',init);}else{init();}})();